import 'package:flutter/material.dart';
import 'package:task_manager/models/database_helper.dart';

class SettingsPage extends StatelessWidget { const SettingsPage({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Settings')), body: ListView(padding: const EdgeInsets.all(24), children: [const ListTile(leading: Icon(Icons.task_alt, color: Colors.green, size: 42), title: Text('Task Manager'), subtitle: Text('Version 1.0')), const Divider(), ListTile(title: const Text('Clear all data'), leading: const Icon(Icons.delete_sweep), onTap: () async { final confirmed = await showDialog<bool>(context: context, builder: (_) => AlertDialog(title: const Text('Delete all tasks?'), content: const Text('This action cannot be undone.'), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Delete'))])); if (confirmed == true) { await DatabaseHelper().deleteAllTasks(); if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('All tasks have been deleted'))); } })])); }
}
